void point2ScreenQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
    float4x4 viewProjInverse, bool isCulled, float depthPriorityUnit, bool orthographic, float DPThresholdInView, 
    inout TriangleStream<geometryInS> outStream  ) 
{ 
	 if(isCulled) return; 
    geometryInS outS  = inputs[0]; 
    float size = max(0, max(pointSz.x, pointSz.y)); 
    float dpScale = orthographic ? 1.0f : -DPThresholdInView; 
    float dp = 2.0f * size * cDepthPriorityUnit * dpScale; 
    float4 sizeInZ = float4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    [unroll] for( int i = 0; i < 4; ++i ) { 
        outS.Pc = inputs[0].Pc + sizeInZ * float4(quadPositionUV[i].xy, 0, 0); 
        outS.Pc.z = inputs[0].Pc.z - dp; 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}


void point2ScreenQuad( AttribArray<geometryInS>inputs, float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
	float4x4 viewProjInverse, bool isCulled, float depthPriorityUnit, bool orthographic, float DPThresholdInView ) 
{ 
	 if(isCulled) return; 
    geometryInS outS = inputs[0]; 
    float size = max(0, max(pointSz.x, pointSz.y)); 
    float dpScale = orthographic ? 1.0f : -DPThresholdInView; 
    float dp = 4.0f * size * cDepthPriorityUnit * dpScale; 
    float4 sizeInZ = float4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    for( int i = 0; i < 4; ++i ) { 
        outS.Pc = inputs[0].Pc + sizeInZ * float4(quadPositionUV[i].xy, 0, 0); 
        outS.Pc.z = inputs[0].Pc.z - dp; 
        emitVertex( outS ); 
    } 
    restartStrip(); 
}


void point2ScreenQuad(  vec2 pointSz, vec2 screenSize, vec4 quadPositionUV[4], 
	mat4x4 viewProjInverse, bool isCulled, float depthPriorityUnit, bool orthographic, float DPThresholdInView ) 
{ 
	 if(isCulled) return; 
    GEO_OUT_struct outS = copyFromGEO_IN(0); 
    float size = max(0, max(pointSz.x, pointSz.y)); 
    float dpScale = orthographic ? 1.0f : -DPThresholdInView; 
    float dp = 4.0f * size * cDepthPriorityUnit * dpScale; 
    vec4 sizeInZ = vec4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    for( int i = 0; i < 4; ++i ) { 
        outS.Pc = gl_in[0].gl_Position + sizeInZ * vec4(quadPositionUV[i].xy, 0, 0); 
        outS.Pc.z = gl_in[0].gl_Position.z - dp; 
        EmitGeoStruct( outS ); 
    } 
    EndPrimitive(); 
}


void point2ScreenQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
    float4x4 viewProjInverse, bool isCulled, float depthPriorityUnit, bool orthographic, float DPThresholdInView, 
    inout TriangleStream<geometryInS> outStream  ) 
{ 
	 if(isCulled) return; 
    geometryInS outS  = inputs[0]; 
    float size = max(0, max(pointSz.x, pointSz.y)); 
    float dpScale = orthographic ? 1.0f : -DPThresholdInView; 
    float dp = 2.0f * size * cDepthPriorityUnit * dpScale; 
    float4 sizeInZ = float4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    [unroll] for( int i = 0; i < 4; ++i ) { 
        outS.Pc = inputs[0].Pc + sizeInZ * float4(quadPositionUV[i].xy, 0, 0); 
        outS.Pc.z = inputs[0].Pc.z - dp; 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}
